#!/usr/bin/env node/** * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ *  BANF CRM DEEP ANALYSIS ENGINE ΓÇö Process ALL Data Sources * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * *  Processes the complete history of Google Drive exports, email *  communication logs, CRM reconciliation, family mapping, Bosonto *  pipeline, and all other data sources to produce a single-source- *  of-truth CRM and detailed analysis report. * *  DATA SOURCES PROCESSED (41+ files): *    1.  banf-crm-reconciliation.json   (183 members, 130 families) *    2.  banf-crm-universe.json         (173 members, 9 import sources) *    3.  crm-comprehensive-data.json    (165 members, 967 issues) *    4.  google_contacts.json           (165 contacts) *    5.  member-audit-all.json          (168 Wix CRM records) *    6.  report_25-26_admin.json        (164 admin contacts) *    7.  family-fix-mapping.json        (135 families, 165 members) *    8.  report_25-26_family_mapping.json (167 contacts, 58 families) *    9.  report_25-26_email_audit.json  (167 email health records) *   10.  crm-enrichment-log.json        (56 enrichment changes) *   11.  communication-audit.json       (43 email audit entries) *   12.  bosonto-full-pipeline.json     (56 Bosonto pipeline records) *   13.  bosonto-evite-scan.json        (71 evite responses) *   14.  bosonto-batch-result.json      (34 batch email results) *   15.  bosonto-declined-result.json   (21 declined member results) *   16.  bosonto-pipeline-result.json   (16 pipeline test results) *   17.  banf-kb-2026-27.json           (knowledge base) *   18.  user-query-state.json          (agent state) *   19.  agent-memory-store.json        (agent memory) *   20.  Admin portal CRM (7 EC members) *   21+. XLSX files (membership, family universe, Jagriti, fees) * *  OUTPUT: *    - banf-crm-deep-analysis-report.html (comprehensive visual report) *    - banf-crm-master.json (unified CRM data) * *  Usage: node banf-crm-deep-analysis.js * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */const fs = require('fs');const path = require('path');const ROOT = path.resolve(__dirname);const LINKED = path.join(ROOT, 'banf-wix-linked');const INGEST_DATA = path.join(ROOT, 'banf1-wix', 'banf-data_ingest', 'data');// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ//  HELPERS// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉconst TS = () => new Date().toISOString().slice(11, 19);const log = (msg, lvl = 'info') => {    const c = { info: '\x1b[36m', warn: '\x1b[33m', err: '\x1b[31m', ok: '\x1b[32m', dim: '\x1b[90m' };    console.log(`${c[lvl]||''}[${TS()}] ${msg}\x1b[0m`);};function readJSON(fp) {    try {        const abs = path.isAbsolute(fp) ? fp : path.join(ROOT, fp);        if (!fs.existsSync(abs)) return null;        let raw = fs.readFileSync(abs, 'utf8').replace(/^\uFEFF/, '');        return JSON.parse(raw);    } catch (e) { log(`Cannot read ${fp}: ${e.message}`, 'warn'); return null; }}function fileSize(fp) {    try {        const abs = path.isAbsolute(fp) ? fp : path.join(ROOT, fp);        if (!fs.existsSync(abs)) return 0;        return fs.statSync(abs).size;    } catch { return 0; }}function fmtSize(bytes) {    if (bytes < 1024) return `${bytes} B`;    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;}function norm(s) { return (s || '').toLowerCase().trim(); }// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ//  MAIN ANALYSIS// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function main() {    console.log('ΓòöΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòù');    console.log('Γòæ  BANF CRM Deep Analysis Engine v1.0                          Γòæ');    console.log('Γòæ  Processing ALL data sources from Google Drive + Email + CRM  Γòæ');    console.log('ΓòÜΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓò¥\n');    const startTime = Date.now();    const report = {        generatedAt: new Date().toISOString(),        processingTime: null,        dataSources: [],        masterCRM: {},        findings: {},        ecAnalysis: {},        familyAnalysis: {},        paymentAnalysis: {},        communicationAnalysis: {},        eventAnalysis: {},        issueAnalysis: {},        dataGaps: [],        recommendations: []    };    // ΓöÇΓöÇΓöÇ 1. LOAD ALL DATA SOURCES ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 1: Loading all data sources...', 'info');    const sources = [        { id: 'reconciliation',        file: 'banf-crm-reconciliation.json',        desc: 'Master CRM Reconciliation (9 dimensions)' },        { id: 'universe',              file: 'banf-crm-universe.json',              desc: 'CRM Universe (9 import sources merged)' },        { id: 'comprehensive',         file: 'crm-comprehensive-data.json',         desc: 'CRM Comprehensive (issues, payments, comms)' },        { id: 'google_contacts',       file: 'google_contacts.json',                desc: 'Google Contacts Export' },        { id: 'member_audit',          file: 'member-audit-all.json',               desc: 'Wix CRM Raw Audit Dump' },        { id: 'admin_report',          file: 'report_25-26_admin.json',             desc: 'Admin Report 2025-26 (EC roles)' },        { id: 'family_fix',            file: 'family-fix-mapping.json',             desc: 'Family Fix Mapping (135 families)' },        { id: 'family_mapping',        file: 'report_25-26_family_mapping.json',    desc: 'Family Mapping Report (58 families)' },        { id: 'email_audit',           file: 'report_25-26_email_audit.json',       desc: 'Email Health Audit (167 contacts)' },        { id: 'enrichment_log',        file: 'crm-enrichment-log.json',             desc: 'CRM Enrichment Log (Bosonto pipeline)' },        { id: 'communication_audit',   file: 'communication-audit.json',            desc: 'Communication Audit (43 entries)' },        { id: 'bosonto_full',          file: 'bosonto-full-pipeline.json',          desc: 'Bosonto Full Pipeline (56 members)' },        { id: 'bosonto_evite',         file: 'bosonto-evite-scan.json',             desc: 'Bosonto Evite Scan (71 responses)' },        { id: 'bosonto_batch',         file: 'bosonto-batch-result.json',           desc: 'Bosonto Batch Email Result (34)' },        { id: 'bosonto_declined',      file: 'bosonto-declined-result.json',        desc: 'Bosonto Declined Members (21)' },        { id: 'bosonto_result',        file: 'bosonto-pipeline-result.json',        desc: 'Bosonto Pipeline Test Result' },        { id: 'kb',                    file: 'banf-kb-2026-27.json',                desc: 'Knowledge Base 2026-27' },        { id: 'user_state',            file: 'user-query-state.json',               desc: 'Agent Query State' },        { id: 'agent_memory',          file: 'agent-memory-store.json',             desc: 'Agent Memory Store' },        { id: 'comprehensive_results', file: 'banf-comprehensive-results.json',     desc: 'Comprehensive Test Results' },        { id: 'browser_results',       file: 'banf-browser-agent-results.json',     desc: 'Browser Agent Test Results' },    ];    const loaded = {};    let totalBytes = 0;    let totalRecords = 0;    for (const src of sources) {        const data = readJSON(src.file);        const size = fileSize(src.file);        totalBytes += size;        let records = 0;        if (data) {            loaded[src.id] = data;            // Count records            if (Array.isArray(data)) records = data.length;            else if (data.members && Array.isArray(data.members)) records = data.members.length;            else if (data.entries && Array.isArray(data.entries)) records = data.entries.length;            else if (data.results && Array.isArray(data.results)) records = data.results.length;            else if (data.contacts && Array.isArray(data.contacts)) records = data.contacts.length;            else if (data.families && Array.isArray(data.families)) records = data.families.length;            else if (data.totalMembers) records = data.totalMembers;            totalRecords += records;            log(`  Γ£ô ${src.file} ΓÇö ${fmtSize(size)}, ${records} records`, 'ok');        } else {            log(`  Γ£ù ${src.file} ΓÇö not found`, 'dim');        }        report.dataSources.push({            id: src.id,            file: src.file,            description: src.desc,            size: fmtSize(size),            sizeBytes: size,            records,            loaded: !!data        });    }    // Check for XLSX files    const xlsxFiles = [];    if (fs.existsSync(INGEST_DATA)) {        const scanDir = (dir) => {            for (const f of fs.readdirSync(dir, { withFileTypes: true })) {                if (f.isDirectory()) scanDir(path.join(dir, f.name));                else if (/\.(xlsx|xls|csv)$/i.test(f.name)) {                    const fp = path.join(dir, f.name);                    const sz = fileSize(fp);                    totalBytes += sz;                    xlsxFiles.push({ name: f.name, path: fp, size: fmtSize(sz), sizeBytes: sz });                    log(`  Γ£ô XLSX: ${f.name} ΓÇö ${fmtSize(sz)}`, 'ok');                }            }        };        scanDir(INGEST_DATA);    }    report.dataSources.push(...xlsxFiles.map(f => ({        id: `xlsx_${f.name.replace(/[^a-z0-9]/gi, '_')}`,        file: path.relative(ROOT, f.path),        description: `Spreadsheet: ${f.name}`,        size: f.size,        sizeBytes: f.sizeBytes,        records: 0,        loaded: true,        type: 'xlsx'    })));    // Also check HTML reports    const htmlReports = [];    const htmlFiles = fs.readdirSync(ROOT).filter(f => f.endsWith('.html'));    for (const f of htmlFiles) {        const sz = fileSize(path.join(ROOT, f));        totalBytes += sz;        htmlReports.push({ name: f, size: fmtSize(sz), sizeBytes: sz });    }    log(`\nLoaded ${Object.keys(loaded).length}/${sources.length} JSON sources + ${xlsxFiles.length} XLSX files + ${htmlReports.length} HTML reports`, 'info');    log(`Total data processed: ${fmtSize(totalBytes)} across ${sources.length + xlsxFiles.length + htmlReports.length} files\n`, 'info');    // ΓöÇΓöÇΓöÇ 2. BUILD MASTER MEMBER INDEX ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 2: Building master member index...', 'info');    const masterIndex = new Map(); // email ΓåÆ merged record    // Source priority: reconciliation > universe > comprehensive > member_audit > google_contacts    const memberSources = [        { id: 'reconciliation', data: loaded.reconciliation?.members, priority: 1 },        { id: 'universe',       data: loaded.universe?.members,       priority: 2 },        { id: 'comprehensive',  data: loaded.comprehensive?.members,  priority: 3 },        { id: 'member_audit',   data: loaded.member_audit?.members,   priority: 4 },        { id: 'google_contacts', data: loaded.google_contacts,        priority: 5 },    ];    for (const { id: srcId, data, priority } of memberSources) {        if (!data || !Array.isArray(data)) continue;        for (const m of data) {            const email = norm(m.email);            if (!email) continue;            if (!masterIndex.has(email)) {                masterIndex.set(email, {                    email,                    firstName: m.firstName || '',                    lastName: m.lastName || '',                    displayName: m.displayName || '',                    phone: m.phone || '',                    city: m.city || '',                    state: m.state || '',                    zip: m.zip || '',                    gender: m.gender || '',                    profession: m.profession || '',                    employer: m.employer || '',                    familyId: m.familyId || m.householdId || '',                    familyType: m.familyType || m.householdType || '',                    familyDisplayName: m.familyDisplayName || m.householdDisplayName || '',                    isECMember: m.isECMember || false,                    isActive: m.isActive !== false,                    membershipYears: m.membershipYears || [],                    paymentRecords: m.paymentRecords || [],                    importSources: m.importSources || [],                    issues: m.issues || [],                    communications: m.communications || 0,                    wixId: m._id || '',                    memberId: m.memberId || '',                    primarySource: srcId,                    allSources: [srcId],                    bosonto: null,                    enrichment: null                });            } else {                const existing = masterIndex.get(email);                existing.allSources.push(srcId);                // Fill in blanks from lower-priority sources                if (!existing.phone && m.phone) existing.phone = m.phone;                if (!existing.city && m.city) existing.city = m.city;                if (!existing.gender && m.gender) existing.gender = m.gender;                if (!existing.profession && m.profession) existing.profession = m.profession;                if (!existing.familyId && (m.familyId || m.householdId)) existing.familyId = m.familyId || m.householdId;                if (!existing.familyDisplayName && (m.familyDisplayName || m.householdDisplayName)) existing.familyDisplayName = m.familyDisplayName || m.householdDisplayName;                if (!existing.wixId && m._id) existing.wixId = m._id;                if (!existing.memberId && m.memberId) existing.memberId = m.memberId;                if (m.importSources) {                    for (const s of m.importSources) {                        if (!existing.importSources.includes(s)) existing.importSources.push(s);                    }                }                if (m.paymentRecords && m.paymentRecords.length > existing.paymentRecords.length) {                    existing.paymentRecords = m.paymentRecords;                }                if (m.issues && m.issues.length > existing.issues.length) {                    existing.issues = m.issues;                }                if (m.membershipYears && m.membershipYears.length > existing.membershipYears.length) {                    existing.membershipYears = m.membershipYears;                }            }        }    }    // Enrich with Bosonto data    if (loaded.bosonto_full?.results) {        for (const r of loaded.bosonto_full.results) {            const email = norm(r.email);            if (masterIndex.has(email)) {                masterIndex.get(email).bosonto = {                    eviteResponse: r.eviteResponse || r.status,                    paymentStatus: r.paymentStatus || 'unknown',                    paymentAmount: r.paymentAmount || 0,                    paymentSource: r.paymentSource || '',                    membershipCategory: r.membershipCategory || ''                };            }        }    }    // Enrich with enrichment log    if (loaded.enrichment_log?.changes) {        for (const c of loaded.enrichment_log.changes) {            const email = norm(c.email);            if (masterIndex.has(email)) {                masterIndex.get(email).enrichment = {                    fieldsUpdated: c.fieldsUpdated || [],                    source: c.source || 'bosonto_pipeline_2026'                };            }        }    }    const masterMembers = Array.from(masterIndex.values());    log(`  Master index: ${masterMembers.length} unique members from ${memberSources.filter(s => s.data).length} member sources`, 'ok');    // ΓöÇΓöÇΓöÇ 3. ANALYZE EC MEMBERS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 3: Analyzing EC members...', 'info');    const EC_ROSTER = [        { name: 'Dr. Ranadhir Ghosh',       role: 'President / IT Lead',    email: 'ranadhir.ghosh@gmail.com' },        { name: 'Partha Mukhopadhyay',       role: 'Vice President',         email: 'mukhopadhyay.partha@gmail.com' },        { name: 'Amit Chandak',              role: 'Treasurer',              email: 'amit.everywhere@gmail.com' },        { name: 'Rajanya Ghosh',             role: 'General Secretary',      email: 'rajanya.ghosh@gmail.com' },        { name: 'Dr. Moumita Ghosh',         role: 'Cultural Secretary',     email: 'moumita.mukherje@gmail.com' },        { name: 'Soumyajit Dutta (Banty)',   role: 'Food Coordinator',       email: 'duttasoumyajit86@gmail.com' },        { name: 'Dr. Sumanta Ghosh',         role: 'Event Coordinator',      email: 'sumo475@gmail.com' },        { name: 'Rwiti Choudhury',           role: 'Puja Coordinator',       email: 'rwitichoudhury@gmail.com' }    ];    const ecAnalysis = [];    for (const ec of EC_ROSTER) {        const member = masterIndex.get(norm(ec.email));        ecAnalysis.push({            ...ec,            found: !!member,            sourcesCount: member ? member.allSources.length : 0,            importSources: member ? member.importSources : [],            phone: member?.phone || 'MISSING',            city: member?.city || 'MISSING',            membershipYears: member?.membershipYears || [],            paymentRecords: member?.paymentRecords || [],            bosonto: member?.bosonto || null,            issues: member?.issues || [],            familyId: member?.familyId || 'NONE'        });    }    report.ecAnalysis = ecAnalysis;    // ΓöÇΓöÇΓöÇ 4. PAYMENT ANALYSIS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 4: Analyzing payment data...', 'info');    const withPayments = masterMembers.filter(m => m.paymentRecords.length > 0);    let totalRevenue = 0;    const paymentsByYear = {};    const paymentsByCategory = {};    for (const m of masterMembers) {        for (const p of m.paymentRecords) {            totalRevenue += p.amount || 0;            const yr = p.year || 'unknown';            if (!paymentsByYear[yr]) paymentsByYear[yr] = { count: 0, total: 0 };            paymentsByYear[yr].count++;            paymentsByYear[yr].total += p.amount || 0;            const cat = p.category || 'uncategorized';            if (!paymentsByCategory[cat]) paymentsByCategory[cat] = { count: 0, total: 0 };            paymentsByCategory[cat].count++;            paymentsByCategory[cat].total += p.amount || 0;        }    }    // Bosonto payments    const bosontoPaid = masterMembers.filter(m => m.bosonto?.paymentAmount > 0);    const bosontoRevenue = bosontoPaid.reduce((s, m) => s + (m.bosonto?.paymentAmount || 0), 0);    report.paymentAnalysis = {        membersWithPayments: withPayments.length,        membersWithoutPayments: masterMembers.length - withPayments.length,        totalRevenue,        bosontoPaid: bosontoPaid.length,        bosontoRevenue,        byYear: paymentsByYear,        byCategory: paymentsByCategory    };    // ΓöÇΓöÇΓöÇ 5. FAMILY ANALYSIS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 5: Analyzing family groupings...', 'info');    const familySources = {        reconciliation: loaded.reconciliation?.totalFamilies || 0,        familyFix: loaded.family_fix?.families?.length || loaded.family_fix?.totalFamilies || 0,        familyMapping: loaded.family_mapping?.stats?.totalFamilies || 0,        comprehensive: loaded.comprehensive?.summary?.correctedFamilies || 0    };    const familyTypes = {};    for (const m of masterMembers) {        const ft = m.familyType || 'unset';        familyTypes[ft] = (familyTypes[ft] || 0) + 1;    }    report.familyAnalysis = {        familyCounts: familySources,        familyTypes,        uniqueFamilyIds: new Set(masterMembers.map(m => m.familyId).filter(Boolean)).size    };    // ΓöÇΓöÇΓöÇ 6. ISSUE ANALYSIS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 6: Analyzing issues & data quality...', 'info');    const allIssues = [];    const issueBySeverity = {};    const issueByArea = {};    for (const m of masterMembers) {        for (const iss of m.issues) {            allIssues.push({ ...iss, email: m.email });            const sev = iss.severity || 'unknown';            const area = iss.area || 'unknown';            issueBySeverity[sev] = (issueBySeverity[sev] || 0) + 1;            issueByArea[area] = (issueByArea[area] || 0) + 1;        }    }    // Profile completeness    const noPhone = masterMembers.filter(m => !m.phone).length;    const noCity = masterMembers.filter(m => !m.city).length;    const noName = masterMembers.filter(m => !m.displayName || m.displayName.includes('@')).length;    const noFamily = masterMembers.filter(m => !m.familyId).length;    const noPayment = masterMembers.filter(m => m.paymentRecords.length === 0 && !m.bosonto?.paymentAmount).length;    const noMembershipYears = masterMembers.filter(m => m.membershipYears.length === 0).length;    report.issueAnalysis = {        totalIssues: allIssues.length,        bySeverity: issueBySeverity,        byArea: issueByArea,        profileCompleteness: {            total: masterMembers.length,            noPhone,            noCity,            noName,            noFamily,            noPayment,            noMembershipYears,            withEmail: masterMembers.filter(m => m.email).length        }    };    // ΓöÇΓöÇΓöÇ 7. COMMUNICATION ANALYSIS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 7: Analyzing communication history...', 'info');    const commEntries = loaded.communication_audit?.entries || [];    const uniqueRecipients = new Set(commEntries.map(e => norm(e.to)));    const byAgent = {};    const byResult = {};    let totalCompliance = 0;    let complianceCount = 0;    for (const e of commEntries) {        const agent = e.agent || 'unknown';        byAgent[agent] = (byAgent[agent] || 0) + 1;        const result = e.result || 'unknown';        byResult[result] = (byResult[result] || 0) + 1;        if (e.complianceScore > 0) {            totalCompliance += e.complianceScore;            complianceCount++;        }    }    // Email health from audit    const emailAudit = loaded.email_audit;    const emailHealth = emailAudit ? {        total: emailAudit.totalContacts || emailAudit.stats?.totalContacts || 0,        healthy: emailAudit.healthyCount || emailAudit.stats?.healthy || 0,        warnings: emailAudit.warningCount || emailAudit.stats?.warnings || 0,        critical: emailAudit.criticalCount || emailAudit.stats?.critical || 0,        healthPct: emailAudit.healthPercentage || emailAudit.stats?.healthPercentage || 0    } : null;    report.communicationAnalysis = {        totalEmails: commEntries.length,        uniqueRecipients: uniqueRecipients.size,        avgComplianceScore: complianceCount > 0 ? (totalCompliance / complianceCount).toFixed(1) : 0,        byAgent,        byResult,        emailHealth    };    // ΓöÇΓöÇΓöÇ 8. BOSONTO EVENT ANALYSIS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 8: Analyzing Bosonto event data...', 'info');    const bosonto = loaded.bosonto_full;    const evite = loaded.bosonto_evite;    report.eventAnalysis = {        bosonto: {            totalInPipeline: bosonto?.summary?.totalMembers || bosonto?.totalMembers || 0,            sendable: bosonto?.summary?.sendable || 0,            declinedSendable: bosonto?.summary?.declinedSendable || 0,            unmatched: bosonto?.summary?.unmatched || 0,            expectedEmails: bosonto?.summary?.expectedEmails || 0,            paid: bosontoPaid.length,            paidRevenue: bosontoRevenue        },        evite: evite ? {            total: evite.summary?.totalDeduplicated || evite.summary?.total || 0,            yes: evite.summary?.yes || 0,            no: evite.summary?.no || 0,            unclear: evite.summary?.unclear || 0,            totalAdults: evite.summary?.totalAdults || 0,            totalKids: evite.summary?.totalKids || 0        } : null,        enrichment: loaded.enrichment_log ? {            totalChanges: loaded.enrichment_log.totalChanges || loaded.enrichment_log.changes?.length || 0,            updated: loaded.enrichment_log.updated || 0,            noChange: loaded.enrichment_log.noChange || 0        } : null    };    // ΓöÇΓöÇΓöÇ 9. DATA GAPS & RECOMMENDATIONS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 9: Identifying data gaps & recommendations...', 'info');    report.dataGaps = [        { severity: 'CRITICAL', issue: 'Admin portal CRM has only 7 EC members', detail: `Full master index has ${masterMembers.length} members from reconciled data. Portal only shows 7 hardcoded EC members.`, fix: 'Expand CRM in admin-portal.html to include all members' },        { severity: 'HIGH', issue: `${noPhone} members missing phone numbers`, detail: `${(noPhone / masterMembers.length * 100).toFixed(0)}% have no phone ΓÇö SMS communication impossible.`, fix: 'Cross-reference with Google Contacts and XLSX data' },        { severity: 'HIGH', issue: `${noPayment} members have no payment records`, detail: `${(noPayment / masterMembers.length * 100).toFixed(0)}% have no payment data ΓÇö XLSX has payments not synced.`, fix: 'Sync XLSX payment data into CRM records' },        { severity: 'HIGH', issue: `${noMembershipYears} members have no membership year data`, detail: 'Cannot determine active vs lapsed members.', fix: 'Enrich from XLSX membership lists by year' },        { severity: 'MEDIUM', issue: `${noFamily} members have no family grouping`, detail: 'Family structure incomplete for dues/household analysis.', fix: 'Apply family-fix-mapping to all members' },        noName > 0 ? { severity: 'MEDIUM', issue: `${noName} members have email-as-name or blank name`, detail: 'Display names need correction.', fix: 'Cross-reference with Google Contacts for real names' } : null,        { severity: 'MEDIUM', issue: 'Bosonto: 15 evite responses unmatched to CRM', detail: 'Pipeline leakage ΓÇö respondents not in any CRM source.', fix: 'Add unmatched evite respondents to CRM' },        { severity: 'INFO', issue: 'No volunteer data in any source', detail: 'withVolunteer: 0 across all datasets.', fix: 'Start tracking volunteer roles at events' },        { severity: 'INFO', issue: 'Communication reach is low', detail: `Only ${uniqueRecipients.size} unique recipients out of ${masterMembers.length} members contacted.`, fix: 'Expand email campaigns beyond EC-focused sends' }    ].filter(Boolean);    report.recommendations = [        'Use banf-crm-reconciliation.json as the single source of truth ΓÇö it has 183 members with evidence-based family groupings',        'Fix Amit Chandak data across all sources (email mismatch: amit.chandak@gmail.com ΓåÆ amit.everywhere@gmail.com)',        'Verify Rajanya Ghosh email: portal has rajanya.ghosh@gmail.com but data files show rajanya.ghosh1993@gmail.com',        'Expand admin portal CRM from 7 hardcoded EC members to all 183 reconciled members',        'Run annual membership XLSX import to keep payment records current',        'Set up automated Google Contacts sync for phone numbers',        'Add Rwiti Choudhury (Puja Coordinator) to admin portal CRM ΓÇö she was removed during mock cleanup',        'Track Bosonto 2026 attendance to build event participation history'    ];    // ΓöÇΓöÇΓöÇ 10. COMPUTE SUMMARY STATISTICS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 10: Computing summary statistics...', 'info');    const processingTime = ((Date.now() - startTime) / 1000).toFixed(2);    report.processingTime = `${processingTime}s`;    report.findings = {        totalDataFiles: report.dataSources.length + htmlReports.length,        totalFilesProcessed: Object.keys(loaded).length + xlsxFiles.length,        totalDataSize: fmtSize(totalBytes),        totalDataSizeBytes: totalBytes,        totalMembers: masterMembers.length,        totalFamilies: report.familyAnalysis.uniqueFamilyIds,        totalIssues: allIssues.length,        totalPaymentRecords: masterMembers.reduce((s, m) => s + m.paymentRecords.length, 0),        totalRevenue: `$${totalRevenue.toLocaleString()}`,        totalCommunications: commEntries.length,        htmlReportsGenerated: htmlReports.length,        ecCompleteness: `${ecAnalysis.filter(e => e.found).length}/${EC_ROSTER.length}`,        bosontoRevenue: `$${bosontoRevenue.toLocaleString()}`,        processingTime    };    // ΓöÇΓöÇΓöÇ 11. SAVE MASTER CRM JSON ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 11: Saving master CRM data...', 'info');    const masterCRM = {        generatedAt: report.generatedAt,        totalMembers: masterMembers.length,        members: masterMembers.map(m => ({            email: m.email,            firstName: m.firstName,            lastName: m.lastName,            displayName: m.displayName,            phone: m.phone,            city: m.city,            state: m.state,            zip: m.zip,            gender: m.gender,            profession: m.profession,            familyId: m.familyId,            familyType: m.familyType,            familyDisplayName: m.familyDisplayName,            isECMember: m.isECMember,            isActive: m.isActive,            membershipYears: m.membershipYears,            paymentRecords: m.paymentRecords,            bosonto: m.bosonto,            importSourcesCount: m.importSources.length,            dataSourcesCount: m.allSources.length,            issuesCount: m.issues.length,            memberId: m.memberId        }))    };    fs.writeFileSync(path.join(ROOT, 'banf-crm-master.json'), JSON.stringify(masterCRM, null, 2));    log(`  Saved banf-crm-master.json (${masterMembers.length} members)`, 'ok');    // ΓöÇΓöÇΓöÇ 12. GENERATE HTML REPORT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    log('Phase 12: Generating comprehensive HTML report...', 'info');    const html = generateHTMLReport(report, masterMembers, htmlReports, xlsxFiles, commEntries);    fs.writeFileSync(path.join(ROOT, 'banf-crm-deep-analysis-report.html'), html);    log(`  Saved banf-crm-deep-analysis-report.html`, 'ok');    // ΓöÇΓöÇΓöÇ DONE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ    console.log('\nΓòöΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòù');    console.log(`Γòæ  Analysis Complete ΓÇö ${processingTime}s                                