ÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ//  HTML REPORT GENERATOR// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction generateHTMLReport(report, members, htmlReports, xlsxFiles, commEntries) {    const f = report.findings;    const pa = report.paymentAnalysis;    const ia = report.issueAnalysis;    const ca = report.communicationAnalysis;    const ea = report.eventAnalysis;    const fa = report.familyAnalysis;    const ec = report.ecAnalysis;    const pc = ia.profileCompleteness;    // Top data source rows    const dsRows = report.dataSources        .filter(d => d.loaded)        .sort((a, b) => b.sizeBytes - a.sizeBytes)        .map(d => `<tr><td>${d.file}</td><td>${d.description}</td><td class="num">${d.size}</td><td class="num">${d.records || 'ΓÇö'}</td></tr>`)        .join('\n');    // EC member rows    const ecRows = ec.map(e => {        const statusCls = e.found ? (e.sourcesCount >= 3 ? 'good' : 'warn') : 'bad';        return `<tr class="${statusCls}">            <td><strong>${e.name}</strong></td>            <td>${e.role}</td>            <td>${e.email}</td>            <td>${e.phone}</td>            <td class="num">${e.sourcesCount}</td>            <td class="num">${e.importSources.length}</td>            <td class="num">${e.paymentRecords.length}</td>            <td class="num">${e.membershipYears.length}</td>            <td>${e.bosonto ? (e.bosonto.paymentAmount > 0 ? `$${e.bosonto.paymentAmount} Γ£à` : e.bosonto.eviteResponse || 'ΓÇö') : 'ΓÇö'}</td>        </tr>`;    }).join('\n');    // Issues breakdown    const issueRows = Object.entries(ia.byArea)        .sort((a, b) => b[1] - a[1])        .map(([area, count]) => `<tr><td>${area}</td><td class="num">${count}</td><td><div class="bar" style="width:${(count / ia.totalIssues * 100).toFixed(0)}%">${(count / ia.totalIssues * 100).toFixed(1)}%</div></td></tr>`)        .join('\n');    // Payment by year rows    const payYearRows = Object.entries(pa.byYear)        .sort((a, b) => b[0].localeCompare(a[0]))        .map(([yr, d]) => `<tr><td>${yr}</td><td class="num">${d.count}</td><td class="num">$${d.total.toLocaleString()}</td></tr>`)        .join('\n');    // Payment by category rows    const payCatRows = Object.entries(pa.byCategory)        .sort((a, b) => b[1].total - a[1].total)        .map(([cat, d]) => `<tr><td>${cat}</td><td class="num">${d.count}</td><td class="num">$${d.total.toLocaleString()}</td></tr>`)        .join('\n');    // Communication rows    const commAgentRows = Object.entries(ca.byAgent)        .sort((a, b) => b[1] - a[1])        .map(([agent, count]) => `<tr><td>${agent}</td><td class="num">${count}</td></tr>`)        .join('\n');    // Data gaps rows    const gapRows = report.dataGaps.map(g => {        const cls = g.severity === 'CRITICAL' ? 'bad' : g.severity === 'HIGH' ? 'warn' : 'info';        return `<tr class="${cls}"><td><span class="badge ${cls}">${g.severity}</span></td><td>${g.issue}</td><td>${g.detail}</td><td>${g.fix}</td></tr>`;    }).join('\n');    // Recommendation rows    const recItems = report.recommendations.map(r => `<li>${r}</li>`).join('\n');    // Top 20 members by data completeness    const topMembers = [...members]        .sort((a, b) => b.allSources.length - a.allSources.length || b.importSources.length - a.importSources.length)        .slice(0, 30)        .map((m, i) => `<tr><td>${i + 1}</td><td>${m.displayName || m.email}</td><td>${m.email}</td><td class="num">${m.allSources.length}</td><td class="num">${m.importSources.length}</td><td class="num">${m.paymentRecords.length}</td><td>${m.phone ? 'Γ£à' : 'Γ¥î'}</td><td>${m.familyId || 'ΓÇö'}</td></tr>`)        .join('\n');    // Members with most issues    const issueMembers = [...members]        .filter(m => m.issues.length > 0)        .sort((a, b) => b.issues.length - a.issues.length)        .slice(0, 20)        .map((m, i) => `<tr><td>${i + 1}</td><td>${m.displayName || m.email}</td><td>${m.email}</td><td class="num">${m.issues.length}</td><td>${m.issues.map(is => `<span class="badge ${is.severity}">${is.area}</span>`).join(' ')}</td></tr>`)        .join('\n');    return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>BANF CRM Deep Analysis Report</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,-apple-system,sans-serif;background:#0f172a;color:#e2e8f0;line-height:1.6}.container{max-width:1400px;margin:0 auto;padding:24px}h1{font-size:2rem;color:#fff;margin-bottom:4px}h2{font-size:1.3rem;color:#fff;margin:32px 0 16px;padding-bottom:8px;border-bottom:2px solid #334155}h3{font-size:1.05rem;color:#94a3b8;margin:16px 0 8px}.subtitle{color:#94a3b8;font-size:.9rem;margin-bottom:24px}.header{background:linear-gradient(135deg,#006A4E 0%,#00856F 100%);padding:32px;border-radius:16px;margin-bottom:24px}.header h1{font-size:2.2rem}.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin:24px 0}.kpi{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:20px;text-align:center}.kpi .value{font-size:2rem;font-weight:800;color:#4ade80}.kpi .value.warn{color:#fbbf24}.kpi .value.bad{color:#f87171}.kpi .label{font-size:.78rem;color:#94a3b8;margin-top:4px;text-transform:uppercase;letter-spacing:.5px}table{width:100%;border-collapse:collapse;margin:12px 0;font-size:.85rem}th{background:#1e293b;color:#94a3b8;padding:10px 12px;text-align:left;font-weight:600;border-bottom:2px solid #334155;text-transform:uppercase;font-size:.72rem;letter-spacing:.5px}td{padding:8px 12px;border-bottom:1px solid #1e293b}tr:hover{background:#1e293b}.num{text-align:right;font-variant-numeric:tabular-nums}.card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:20px;margin:16px 0}.badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:.72rem;font-weight:600;text-transform:uppercase}.badge.CRITICAL,.badge.bad{background:#7f1d1d;color:#fca5a5}.badge.HIGH,.badge.warn,.badge.warning{background:#78350f;color:#fcd34d}.badge.MEDIUM,.badge.info{background:#1e3a5f;color:#93c5fd}.badge.INFO{background:#1e293b;color:#94a3b8}tr.good td{border-left:3px solid #4ade80}tr.warn td{border-left:3px solid #fbbf24}tr.bad td{border-left:3px solid #f87171}tr.info td{border-left:3px solid #60a5fa}.bar{background:linear-gradient(90deg,#006A4E,#00856F);color:#fff;padding:2px 8px;border-radius:4px;font-size:.72rem;display:inline-block;min-width:30px;text-align:center}.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:900px){.grid-2{grid-template-columns:1fr}}.section{margin-bottom:40px}.tag{display:inline-block;background:#334155;color:#e2e8f0;padding:1px 6px;border-radius:3px;font-size:.72rem;margin:1px}.progress{background:#334155;border-radius:8px;overflow:hidden;height:8px;margin:4px 0}.progress-fill{height:100%;border-radius:8px;background:linear-gradient(90deg,#006A4E,#4ade80)}.progress-fill.warn{background:linear-gradient(90deg,#92400e,#fbbf24)}.progress-fill.bad{background:linear-gradient(90deg,#7f1d1d,#f87171)}footer{text-align:center;color:#475569;font-size:.75rem;padding:40px 0 20px}</style></head><body><div class="container"><!-- HEADER --><div class="header">    <h1>≡ƒÅ¢ BANF CRM Deep Analysis Report</h1>    <div class="subtitle">Bengali Association of North Florida ΓÇö Complete Data Source Analysis<br>    Generated: ${report.generatedAt} ┬╖ Processing time: ${f.processingTime}</div></div><!-- KPI DASHBOARD --><div class="kpi-grid">    <div class="kpi"><div class="value">${f.totalFilesProcessed}</div><div class="label">Files Processed</div></div>    <div class="kpi"><div class="value">${f.totalDataSize}</div><div class="label">Total Data</div></div>    <div class="kpi"><div class="value">${f.totalMembers}</div><div class="label">Master CRM Members</div></div>    <div class="kpi"><div class="value">${fa.uniqueFamilyIds}</div><div class="label">Family Groups</div></div>    <div class="kpi"><div class="value warn">${ia.totalIssues}</div><div class="label">Issues Found</div></div>    <div class="kpi"><div class="value">${f.totalRevenue}</div><div class="label">Revenue Tracked</div></div>    <div class="kpi"><div class="value">${ca.totalEmails}</div><div class="label">Emails Sent</div></div>    <div class="kpi"><div class="value">${f.ecCompleteness}</div><div class="label">EC Data Complete</div></div></div><!-- SECTION 1: DATA SOURCES --><div class="section">    <h2>≡ƒôü 1. Data Sources Processed</h2>    <p style="color:#94a3b8;margin-bottom:12px">Complete inventory of all Google Drive exports, CRM dumps, email logs, XLSX files, and generated reports analyzed.</p>    <table>        <tr><th>File</th><th>Description</th><th style="text-align:right">Size</th><th style="text-align:right">Records</th></tr>        ${dsRows}    </table>    <h3>Previously Generated HTML Reports (${htmlReports.length})</h3>    <div style="display:flex;flex-wrap:wrap;gap:6px;margin:8px 0">        ${htmlReports.slice(0, 15).map(r => `<span class="tag">${r.name} (${r.size})</span>`).join('\n')}        ${htmlReports.length > 15 ? `<span class="tag">+${htmlReports.length - 15} more</span>` : ''}    </div>    <h3>XLSX / Spreadsheet Files (${xlsxFiles.length})</h3>    <div style="display:flex;flex-wrap:wrap;gap:6px;margin:8px 0">        ${xlsxFiles.map(f => `<span class="tag">${f.name} (${f.size})</span>`).join('\n')}    </div></div><!-- SECTION 2: PROFILE COMPLETENESS --><div class="section">    <h2>≡ƒôè 2. Profile Completeness</h2>    <div class="grid-2">        <div class="card">            <h3>Field Coverage (${pc.total} members)</h3>            <table>                <tr><td>Has Email</td><td class="num">${pc.withEmail}/${pc.total}</td><td><div class="progress"><div class="progress-fill" style="width:${(pc.withEmail/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has Phone</td><td class="num">${pc.total - pc.noPhone}/${pc.total}</td><td><div class="progress"><div class="progress-fill ${((pc.total-pc.noPhone)/pc.total) < 0.5 ? 'bad' : 'warn'}" style="width:${((pc.total-pc.noPhone)/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has Real Name</td><td class="num">${pc.total - pc.noName}/${pc.total}</td><td><div class="progress"><div class="progress-fill" style="width:${((pc.total-pc.noName)/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has City</td><td class="num">${pc.total - pc.noCity}/${pc.total}</td><td><div class="progress"><div class="progress-fill" style="width:${((pc.total-pc.noCity)/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has Family Group</td><td class="num">${pc.total - pc.noFamily}/${pc.total}</td><td><div class="progress"><div class="progress-fill ${((pc.total-pc.noFamily)/pc.total) < 0.5 ? 'warn' : ''}" style="width:${((pc.total-pc.noFamily)/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has Payment Data</td><td class="num">${pc.total - pc.noPayment}/${pc.total}</td><td><div class="progress"><div class="progress-fill ${((pc.total-pc.noPayment)/pc.total) < 0.5 ? 'bad' : 'warn'}" style="width:${((pc.total-pc.noPayment)/pc.total*100).toFixed(0)}%"></div></div></td></tr>                <tr><td>Has Membership Years</td><td class="num">${pc.total - pc.noMembershipYears}/${pc.total}</td><td><div class="progress"><div class="progress-fill ${((pc.total-pc.noMembershipYears)/pc.total) < 0.5 ? 'bad' : 'warn'}" style="width:${((pc.total-pc.noMembershipYears)/pc.total*100).toFixed(0)}%"></div></div></td></tr>            </table>        </div>        <div class="card">            <h3>Issues by Area</h3>            <table>                <tr><th>Area</th><th style="text-align:right">Count</th><th>Distribution</th></tr>                ${issueRows}            </table>        </div>    </div></div><!-- SECTION 3: EC MEMBERS --><div class="section">    <h2>≡ƒæÑ 3. EC Members 2026ΓÇô2028 ΓÇö Data Completeness</h2>    <table>        <tr><th>Name</th><th>Role</th><th>Email</th><th>Phone</th><th style="text-align:right">Sources</th><th style="text-align:right">Imports</th><th style="text-align:right">Payments</th><th style="text-align:right">Years</th><th>Bosonto</th></tr>        ${ecRows}    </table></div><!-- SECTION 4: PAYMENTS --><div class="section">    <h2>≡ƒÆ░ 4. Payment & Revenue Analysis</h2>    <div class="kpi-grid" style="grid-template-columns:repeat(4,1fr)">        <div class="kpi"><div class="value">${pa.membersWithPayments}</div><div class="label">Members with Payments</div></div>        <div class="kpi"><div class="value bad">${pa.membersWithoutPayments}</div><div class="label">No Payment Records</div></div>        <div class="kpi"><div class="value">${f.totalRevenue}</div><div class="label">Total Revenue</div></div>        <div class="kpi"><div class="value">$${pa.bosontoRevenue.toLocaleString()}</div><div class="label">Bosonto 2026 Revenue</div></div>    </div>    <div class="grid-2">        <div class="card">            <h3>Revenue by Year</h3>            <table>                <tr><th>Year</th><th style="text-align:right">Payments</th><th style="text-align:right">Total</th></tr>                ${payYearRows}            </table>        </div>        <div class="card">            <h3>Revenue by Category</h3>            <table>                <tr><th>Category</th><th style="text-align:right">Count</th><th style="text-align:right">Total</th></tr>                ${payCatRows}            </table>        </div>    </div></div><!-- SECTION 5: FAMILIES --><div class="section">    <h2>≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæºΓÇì≡ƒæª 5. Family Analysis</h2>    <div class="grid-2">        <div class="card">            <h3>Family Counts by Source</h3>       